    if (existsSync(join(dir, ".git"))) return dir;
    const parent = dirname(dir);
    if (parent === dir) return null;
    dir = parent;
  }
}

const FILES = [".stackpilot/CLAUDE.md", "CLAUDE.md"] as const;

function readOptional(path: string): string | null {
  try {
    return readFileSync(path, "utf8").trim();
  } catch {
    return null;
  }
}

function collectInDir(dir: string): string | null {
  for (const rel of FILES) {
    const content = readOptional(join(dir, rel));
    if (content) return content;
  }
  return null;
}

export function loadInstructions(cwd: string, home: string): string {
  const sections: string[] = [];
  const gitRoot = findGitRoot(cwd);
  const stopAt = gitRoot ?? home;
  let dir = resolve(cwd);

  for (;;) {
    const content = collectInDir(dir);
    if (content) {
      sections.unshift(`# From ${join(dir, ".stackpilot/CLAUDE.md" === dir + "/.stackpilot/CLAUDE.md" ? ".stackpilot/CLAUDE.md" : "CLAUDE.md")}:`);
      sections.unshift(content);
    }
    if (dir === stopAt) break;
    const parent = dirname(dir);
    if (parent === dir) break;
    dir = parent;
  }

  const userContent = readOptional(join(home, ".stackpilot", "CLAUDE.md"));
  if (userContent && sections.length === 0) {
    sections.push(userContent);
  } else if (userContent) {
    sections.push(
      "",
      "# User-level instructions (~/.stackpilot/CLAUDE.md):",
