{"filePath": "/Users/demo/Projects/aitools/stackpilot/src/core/hooks.ts", "content": "import { execFile } from "node:child_process";

export type HookPoint = "pre-tool" | "post-tool";

export interface HookConfig {
  command: string;
  timeoutMs: number;
}

export interface HookContext {
  hook: HookPoint;
  tool: string;
  input: Record<string, unknown>;
  sessionId: string;
  cwd: string;
  timestamp: string;
}

export interface HookResult {
  stdout: string;
  stderr: string;
  exitCode: number;
  timedOut: boolean;
}

const DEFAULT_TIMEOUT_MS = 5000;

function buildContext(
  hook: HookPoint,
  tool: string,
  input: Record<string, unknown>,
  sessionId: string,
  cwd: string,
): HookContext {
  return {
    hook,
    tool,
    input,
    sessionId,
    cwd,
    timestamp: new Date().toISOString(),
  };
}

export async function runHook(
  hook: HookPoint,
  config: HookConfig | undefined,
  tool: string,
  input: Record<string, unknown>,
  sessionId: string,
  cwd: string,
): Promise<HookResult | null> {
  if (!config || !config.command) return null;

  const ctx = buildContext(hook, tool, input, sessionId, cwd);
  const stdin = JSON.stringify(ctx);
  const timeoutMs = config.timeoutMs || DEFAULT_TIMEOUT_MS;

  return new Promise<HookResult>((resolve) => {
    const child = execFile(
      config.command,
      [],
      {
        cwd,
        timeout: timeoutMs,
        maxBuffer: 50 * 1024,
        env: { ...process.env, STACKPILOT_HOOK: hook, STACKPILOT_TOOL: tool },
      },
      (err, stdout, stderr) => {
        resolve({
          stdout: stdout.trim(),
          stderr: stderr.trim(),
          exitCode: err ? (err as NodeJS.ErrnoException).code === "ERR_CHILD_PROCESS_STDIO_MAXBUFFER" ? 1 : ((err as { code?: number }).code ?? 1) : 0,
          timedOut: err?.killed ?? false,
        });
      },
    );

    if (child.stdin) {
      child.stdin.write(stdin);
      child.stdin.end();
    }
  });
}
"}

