      ...numbered,
      dim(cyan(`└${"─".repeat(78)}`)),
    ].join("\n");
  }
}

function renderInline(line: string): string {
  let out = line;

  out = out.replace(/\*\*(\S[^*]*\S|\S)\*\*/g, (_, m: string) => bold(m));
  out = out.replace(/\*(\S[^*]*\S|\S)\*/g, (_, m: string) => italic(m));
