// Replaces inline scrolling with a Claude-like layout where the output area
// scrolls and the input/stats lines are always visible at the bottom.

import process from "node:process";
import { createInterface, type Interface } from "node:readline/promises";

// Output lines buffer — append-only, rendered from the end.
const BUFFER_MAX = 5000;

export class Screen {
  private buffer: string[] = [];
  private height = 0;
  private width = 0;
  private statsLine = "";
  private onResize?: () => void;

  init(ttyIn: NodeJS.ReadStream, ttyOut: NodeJS.WriteStream): void {
    this.size(ttyOut.rows, ttyOut.columns);
    // Enter alternate screen buffer
    ttyOut.write("\x1b[?1049h");
    ttyOut.write("\x1b[?25l"); // hide cursor
    ttyOut.write("\x1b[2J"); // clear

    const onSigwinch = (): void => {
      this.size(ttyOut.rows, ttyOut.columns);
      this.redraw(ttyOut);
      this.onResize?.();
    };
    process.on("SIGWINCH", onSigwinch);
  }

  private size(h: number, w: number): void {
    this.height = h;
    this.width = w;
  }

  // Call after init to register a resize callback.
  setOnResize(fn: () => void): void {
    this.onResize = fn;
  }

  destroy(ttyOut: NodeJS.WriteStream): void {
    ttyOut.write("\x1b[?25h"); // show cursor
    ttyOut.write("\x1b[?1049l"); // exit alternate screen
  }

  write(text: string): void {
    const lines = text.split("\n");
    for (const l of lines) {
      while (this.buffer.length >= BUFFER_MAX) this.buffer.shift();
      this.buffer.push(l);
    }
  }

  setStats(line: string): void {
    this.statsLine = line;
  }

  // Redraw the entire screen. Called after output changes or resize.
  redraw(out: NodeJS.WriteStream): void {
    const h = this.height;
    const w = this.width;
    const inputRows = 2; // stats + input line
    const visible = Math.max(1, h - inputRows);
    const startIdx = Math.max(0, this.buffer.length - visible);

    out.write("\x1b[H"); // home
    // Output area
    for (let i = 0; i < visible; i++) {
      const idx = startIdx + i;
      const line = idx < this.buffer.length ? this.buffer[idx] ?? "" : "";
      out.write("\x1b[K");
      if (line) out.write(clip(line, w));
      if (i < visible - 1) out.write("\n");
    }

    // Stats line
    out.write(`\x1b[${h - 1};1H\x1b[K`);
    if (this.statsLine) out.write(clip(this.statsLine, w));

    // Input line — just position, caller writes prompt
    out.write(`\x1b[${h};1H\x1b[K`);
  }

  // Read a line of input. Blocks until Enter. Returns null on Esc/Ctrl-C.
  // Manages its own cursor on the input line.
  async readLine(
    ttyIn: NodeJS.ReadStream,
    ttyOut: NodeJS.WriteStream,
  ): Promise<string | null> {
    const prompt = "› ";

    // Position cursor and write prompt
    ttyOut.write(`\x1b[${this.height};1H\x1b[K`);
    ttyOut.write(prompt);
    ttyOut.write("\x1b[?25h"); // show cursor

    let input = "";
    let cursor = 0;
    const history: string[] = [];
    let histIdx = -1;

    return new Promise<string | null>((resolve) => {
      const onData = (buf: Buffer): void => {
        const str = buf.toString();
        for (let i = 0; i < str.length; i++) {
          const ch = str[i]!;
          const code = ch.charCodeAt(0);

          if (code === 13) {
            // Enter
            ttyIn.off("data", onData);
            ttyOut.write("\n");
            if (input.trim()) history.push(input);
            resolve(input.trim() || null);
            return;
          }

          if (code === 27) {
            // Escape sequences
            if (str[i + 1] === "[" && str[i + 2] !== undefined) {
              const seq = str[i + 2]!;
              i += 2;
              if (seq === "A") {
                // Up arrow — history
                if (histIdx === -1) histIdx = history.length;
                if (histIdx > 0) {
                  histIdx--;
                  input = history[histIdx] ?? "";
                  cursor = input.length;
                }
              } else if (seq === "B") {
                // Down arrow — history
                if (histIdx >= 0) {
                  histIdx++;
                  input =
                    histIdx < history.length
                      ? (history[histIdx] ?? "")
                      : "";
                  cursor = input.length;
                  if (histIdx >= history.length) histIdx = -1;
                }
              } else if (seq === "C" && cursor < input.length) {
                // Right
                cursor++;
              } else if (seq === "D" && cursor > 0) {
                // Left
                cursor--;
              }
            } else {
              // Escape alone — cancel
              ttyIn.off("data", onData);
              ttyOut.write("\n");
              resolve(null);
              return;
            }
          } else if (code === 127) {
            // Backspace
            if (cursor > 0) {
              input =
                input.slice(0, cursor - 1) + input.slice(cursor);
              cursor--;
            }
          } else if (code === 3) {
            // Ctrl-C
            ttyIn.off("data", onData);
            ttyOut.write("^C\n");
            ttyOut.write("\x1b[?1049l");
            resolve(null);
            return;
          } else if (code >= 32) {
            // Printable
            input =
              input.slice(0, cursor) + ch + input.slice(cursor);
            cursor++;
          }

          // Redraw input line
          ttyOut.write(`\x1b[${this.height};1H\x1b[K`);
          ttyOut.write(prompt + input);
          // Position cursor
          ttyOut.write(
            `\x1b[${this.height};${prompt.length + cursor + 1}H`,
          );
        }
      };

      ttyIn.on("data", onData);
    });
  }
}

function clip(s: string, w: number): string {
  return s.length > w ? s.slice(0, w - 1) + "…" : s;
}
"}

