// top area so normal output scrolls freely while the input line stays pinned
// at the bottom. No alternate screen buffer — compatible with clack prompts
// and readline keypress events.

function getSize(
  out: NodeJS.WriteStream,
): { rows: number; cols: number } {
  return { rows: out.rows, cols: out.columns };
}

export class Screen {
  private rows = 0;
  private cols = 0;

  init(out: NodeJS.WriteStream): void {
    const { rows, cols } = getSize(out);
    this.rows = rows;
    this.cols = cols;
    this.setRegion(out);
  }

  private setRegion(out: NodeJS.WriteStream): void {
    // Pin bottom 2 lines (stats + input). Content scrolls in lines 1..rows-2.
    const topRows = Math.max(1, this.rows - 2);
    out.write(`\x1b[1;${topRows}r`);
  }

  redraw(out: NodeJS.WriteStream): void {
    const { rows, cols } = getSize(out);
    if (rows !== this.rows || cols !== this.cols) {
      this.rows = rows;
      this.cols = cols;
      out.write("\x1b[r");
      this.setRegion(out);
    }
  }

  showStats(out: NodeJS.WriteStream, line: string): void {
    const row = Math.max(1, this.rows - 1);
    out.write(`\x1b7\x1b[${row};1H\x1b[K${clip(line, this.cols)}\x1b8`);
  }

  showPrompt(out: NodeJS.WriteStream, prompt: string): void {
    const row = this.rows;
    out.write(`\x1b7\x1b[${row};1H\x1b[K${prompt}\x1b8`);
  }

  positionInput(out: NodeJS.WriteStream): void {
    // Move cursor to bottom row for readline input
    out.write(`\x1b[${this.rows};1H`);
  }

  restore(out: NodeJS.WriteStream): void {
    out.write("\x1b[r");
  }
}

function clip(s: string, w: number): string {
  return s.length > w ? s.slice(0, w - 1) + "…" : s;
}
"}

