// Output lines are buffered and rendered from the end; the bottom area
// (input + stats) always stays visible.

const MAX_LINES = 2000;

export class Screen {
  private lines: string[] = [];
  private height = 24;
  private width = 80;

  init(out: NodeJS.WriteStream): void {
    this.height = out.rows;
    this.width = out.columns;
    out.write("\x1b[?1049h");
    out.write("\x1b[?25l");
  }

  destroy(out: NodeJS.WriteStream): void {
    out.write("\x1b[?25h");
    out.write("\x1b[?1049l");
  }

  resize(out: NodeJS.WriteStream): void {
    this.height = out.rows;
    this.width = out.columns;
  }

  write(text: string): void {
    for (const l of text.split("\n")) {
      if (this.lines.length >= MAX_LINES) this.lines.shift();
      this.lines.push(clip(l, this.width));
    }
  }

  redraw(
    out: NodeJS.WriteStream,
    statsLine: string,
    inputLine: string,
  ): void {
    const visible = Math.max(1, this.height - 3);
    const startIdx = Math.max(0, this.lines.length - visible);

    out.write("\x1b[H");
    for (let i = 0; i < visible; i++) {
      const idx = startIdx + i;
      const line = idx < this.lines.length ? (this.lines[idx] ?? "") : "";
      out.write(`\x1b[K${line}\n`);
    }

    // Separator + stats
    const sep = dim2("─".repeat(this.width));
    out.write(`\x1b[K${sep}\n`);
    out.write(`\x1b[K${clip(statsLine, this.width)}\n`);

    // Input line
    out.write(`\x1b[K› ${inputLine}`);
    // Cursor position
    const cursorCol = 2 + inputLine.length;
    out.write(`\x1b[${this.height};${cursorCol}H`);
    out.write("\x1b[?25h");
  }
}

function clip(s: string, w: number): string {
  if (s.length <= w) return s;
  return s.slice(0, w - 1) + "…";
}

function dim2(s: string): string {
  return `\x1b[2m${s}\x1b[22m`;
}
"}

