// Uses readline's keypress events for reliable escape-sequence handling.

import { emitKeypressEvents } from "node:readline";
import type { Interface } from "node:readline";

const MAX_LINES = 2000;

export class Screen {
  private lines: string[] = [];
  private height = 24;
  private width = 80;

  init(out: NodeJS.WriteStream): void {
    this.height = out.rows;
    this.width = out.columns;
    out.write("\x1b[?1049h");
    out.write("\x1b[?25l");
  }

  destroy(out: NodeJS.WriteStream): void {
    out.write("\x1b[?25h");
    out.write("\x1b[?1049l");
  }

  resize(out: NodeJS.WriteStream): void {
    this.height = out.rows;
    this.width = out.columns;
  }

  write(text: string): void {
    for (const l of text.split("\n")) {
      if (this.lines.length >= MAX_LINES) this.lines.shift();
      this.lines.push(clip(l, this.width));
    }
  }

  clearOutput(): void {
    this.lines = [];
  }

  redraw(
    out: NodeJS.WriteStream,
    statsLine: string,
    inputLine: string,
  ): void {
    const visible = Math.max(1, this.height - 3);
    const startIdx = Math.max(0, this.lines.length - visible);

    out.write("\x1b[H");
    for (let i = 0; i < visible; i++) {
      const idx = startIdx + i;
      const line = idx < this.lines.length ? (this.lines[idx] ?? "") : "";
      out.write(`\x1b[K${line}\n`);
    }

    const sep = dim2("─".repeat(this.width));
    out.write(`\x1b[K${sep}\n`);
    out.write(`\x1b[K${clip(statsLine, this.width)}\n`);

    out.write(`\x1b[K› ${inputLine}`);
    const cursorCol = 2 + inputLine.length;
    out.write(`\x1b[${this.height};${cursorCol}H`);
    out.write("\x1b[?25h");
  }

  // --- Input (uses readline keypress events) -------------------------------

  private inputActive = false;
  private inputLine = "";
  private inputCursor = 0;
  private resolveInput: ((value: string | null) => void) | null = null;
  private rl: Interface | null = null;
  private history: string[] = [];
  private histIdx = -1;

  private onKey(str: string, key: { name?: string; ctrl?: boolean }): void {
    if (!this.inputActive || !this.resolveInput) return;

    if (key.name === "return") {
      this.inputActive = false;
      const line = this.inputLine;
      this.inputLine = "";
      this.inputCursor = 0;
      this.histIdx = -1;
      if (line.trim()) this.history.push(line);
      this.resolveInput(line.trim() || null);
      return;
    }

    if (key.name === "escape" || (key.name === "c" && key.ctrl)) {
      this.inputActive = false;
      const line = this.inputLine;
      this.inputLine = "";
      this.inputCursor = 0;
      this.histIdx = -1;
      // Esc returns null (cancel), Ctrl-C also null
      this.resolveInput(null);
      return;
    }

    if (key.name === "backspace") {
      if (this.inputCursor > 0) {
        this.inputLine =
          this.inputLine.slice(0, this.inputCursor - 1) +
          this.inputLine.slice(this.inputCursor);
        this.inputCursor--;
      }
      return;
    }

    if (key.name === "up") {
      if (this.histIdx === -1) this.histIdx = this.history.length;
      if (this.histIdx > 0) {
        this.histIdx--;
        this.inputLine = this.history[this.histIdx] ?? "";
        this.inputCursor = this.inputLine.length;
      }
      return;
    }

    if (key.name === "down") {
      if (this.histIdx >= 0) {
        this.histIdx++;
        if (this.histIdx < this.history.length) {
          this.inputLine = this.history[this.histIdx] ?? "";
        } else {
          this.inputLine = "";
          this.histIdx = -1;
        }
        this.inputCursor = this.inputLine.length;
      }
      return;
    }

    if (key.name === "left" && this.inputCursor > 0) {
      this.inputCursor--;
      return;
    }

    if (key.name === "right" && this.inputCursor < this.inputLine.length) {
      this.inputCursor++;
      return;
    }

    // Printable: insert at cursor
    if (str && str.length === 1 && str.charCodeAt(0) >= 32) {
      this.inputLine =
        this.inputLine.slice(0, this.inputCursor) +
        str +
        this.inputLine.slice(this.inputCursor);
      this.inputCursor++;
    }
  }

  async readLine(
    ttyIn: NodeJS.ReadStream,
    ttyOut: NodeJS.WriteStream,
    statsLine: string,
  ): Promise<string | null> {
    if (!this.rl) {
      emitKeypressEvents(ttyIn);
      this.rl = (ttyIn as unknown as { _interface?: Interface })._interface ??
        (null as unknown as Interface);
    }

    this.inputLine = "";
    this.inputCursor = 0;
    this.inputActive = true;

    return new Promise<string | null>((resolve) => {
      this.resolveInput = resolve;
      ttyIn.on("keypress", this.onKey.bind(this));
      ttyIn.resume();
      this.redraw(ttyOut, statsLine, "");
    });
  }

  stopInput(ttyIn: NodeJS.ReadStream): void {
    this.inputActive = false;
    this.resolveInput = null;
    ttyIn.off("keypress", this.onKey.bind(this));
  }
}

function clip(s: string, w: number): string {
  if (s.length <= w) return s;
  return s.slice(0, w - 1) + "…";
}

function dim2(s: string): string {
  return `\x1b[2m${s}\x1b[22m`;
}
"}

