// input + status (bottom). Alternate screen buffer with manual rendering.

import { emitKeypressEvents } from "node:readline";
import type { Interface } from "node:readline";

const MAX_LINES = 3000;
const TOP_LINES = 2;
const BOTTOM_LINES = 3;

export class Screen {
  private lines: string[] = [];
  private topContent: string[] = [];
  private height = 24;
  private width = 80;

  init(out: NodeJS.WriteStream): void {
    this.height = out.rows;
    this.width = out.columns;
    out.write("\x1b[?1049h");
    out.write("\x1b[?25l");
  }

  destroy(out: NodeJS.WriteStream): void {
    out.write("\x1b[?25h");
    out.write("\x1b[?1049l");
  }

  resize(out: NodeJS.WriteStream): void {
    this.height = out.rows;
    this.width = out.columns;
  }

  setTop(lines: string[]): void {
    this.topContent = lines;
  }

  write(text: string): void {
    for (const l of text.split("\n")) {
      if (this.lines.length >= MAX_LINES) this.lines.shift();
      this.lines.push(clip(l, this.width));
    }
  }

  clearOutput(): void {
    this.lines = [];
  }

  redraw(
    out: NodeJS.WriteStream,
    statusLine: string,
    inputLine: string,
  ): void {
    const middleRows = Math.max(1, this.height - TOP_LINES - BOTTOM_LINES);
    const startIdx = Math.max(0, this.lines.length - middleRows);
    const sep = dim2("─".repeat(this.width));

    out.write("\x1b[H");

    // Top pane: metadata
    for (let i = 0; i < TOP_LINES; i++) {
      const line = i < this.topContent.length ? (this.topContent[i] ?? "") : "";
      out.write(`\x1b[K${clip(line, this.width)}\n`);
    }
    out.write(`\x1b[K${sep}\n`);

    // Middle pane: response output
    for (let i = 0; i < middleRows; i++) {
      const idx = startIdx + i;
      const line = idx < this.lines.length ? (this.lines[idx] ?? "") : "";
      out.write(`\x1b[K${line}\n`);
    }
    out.write(`\x1b[K${sep}\n`);

    // Bottom pane: status line
    out.write(`\x1b[K${clip(statusLine, this.width)}\n`);
    // Input line
    out.write(`\x1b[K› ${inputLine}`);
    const cursorCol = 3 + inputLine.length; // "› " = 2 chars
    out.write(`\x1b[${this.height};${cursorCol}H`);
    out.write("\x1b[?25h");
  }

